    "body{margin:0;padding:24px;background:#fff;font-family:-apple-system,'PingFang SC','Noto Sans CJK SC',"
    "'Microsoft YaHei',sans-serif;}table{border-collapse:collapse;font-size:18px;line-height:1.5;color:#0f1419;}"
