        if not p.is_file() or ".git" in p.parts:
            continue
        rel = p.relative_to(ROOT).as_posix()
        if any(rx.search(rel) for rx in IGNORE_RES):
            continue
        for rx in EXCLUDE_RES:
            if rx.search(rel):
                fail(f"不应进包的文件: {rel}")
                break
